import { childcareSource } from './planning-childcare-data.js';

export const paymentWorkDefinitions={
  rrspCash:{title:'Explore one ordinary RRSP withdrawal outside Quebec',fields:[
    ['gross','Single gross RRSP withdrawal request (CAD)',10000,0,100000,500],['taxEstimate','Assumed effective incremental final tax / withdrawal (%)',30,0,55,5],
    ['fee','Separate transaction fee paid from other cash (CAD)',50,0,1000,25],['spendingNeed','Cash needed for the intended spending (CAD)',7000,0,100000,500]
  ]},
  oasRecovery:{title:'Explore a 2025 OAS recovery illustration and its later cash period',fields:[
    ['income','Adjusted income for the 2025 recovery calculation (CAD)',100000,0,500000,1000],['annualOAS','Gross OAS received in 2025, excluding supplements (CAD)',9000,0,15000,500],
    ['monthlyOAS','Hypothetical gross monthly OAS throughout Jan 2026–Jun 2027 (CAD)',750,0,2000,50],['oldDeduction','Prior monthly recovery deduction used for Jan–Jun 2026 (CAD)',0,0,2000,25]
  ]},
  returnWork:{title:'Explore the household cash change from returning to work',fields:[
    ['netPay','Additional monthly take-home work pay (CAD)',3500,0,12000,250],['care','Additional monthly child-care cost for the household (CAD)',800,0,5000,100],
    ['commute','Additional monthly commuting costs (CAD)',200,0,2000,50],['otherWork','Other additional monthly work costs (CAD)',150,0,2000,50],
    ['lostIncome','Other net household income lost each month (CAD)',500,0,5000,100],['setup','One-time return-to-work setup cost (CAD)',1500,0,20000,250],
    ['months','Full monthly periods after returning',12,1,24,1]
  ]}
};
export const paymentRules={
  reviewed:'2026-10-25',rrspUrl:'https://www.canada.ca/en/revenue-agency/services/tax/individuals/topics/rrsps-related-plans/making-withdrawals/tax-rates-on-withdrawals.html',
  oasUrl:'https://www.canada.ca/en/services/benefits/publicpensions/old-age-security/repayment.html',oasIncomeYear:2025,oasThreshold:93454,oasRate:.15
};
const cents=value=>Math.round(value*100+1e-7)/100;
export function rrspWithholdingRate(gross){return gross<=0?0:gross<=5000?.1:gross<=15000?.2:.3;}
export function rrspWithdrawalCash(input){
  const rate=rrspWithholdingRate(input.gross),withheld=cents(input.gross*rate),fee=input.gross>0?input.fee:0;
  const immediate=input.gross-withheld-fee,estimatedTax=input.gross*input.taxEstimate/100,settlement=estimatedTax-withheld;
  const afterTax=input.gross-estimatedTax-fee;
  return {rate,withheld,fee,immediate,estimatedTax,settlement,afterTax,spendingBalance:afterTax-input.spendingNeed};
}
export function oasRecoveryPlan(input){
  const excess=Math.max(0,input.income-paymentRules.oasThreshold),recovery=Math.min(input.annualOAS,excess*paymentRules.oasRate);
  const monthlyDeduction=Math.min(input.monthlyOAS,cents(recovery/12)),oldDeduction=Math.min(input.monthlyOAS,input.oldDeduction);
  const rows=Array.from({length:18},(_,i)=>({x:i+1,gross:input.monthlyOAS,deduction:i<6?oldDeduction:monthlyDeduction,retained:input.monthlyOAS-(i<6?oldDeduction:monthlyDeduction)}));
  return {excess,recovery,retainedAnnual:input.annualOAS-recovery,monthlyDeduction,monthlyRetained:input.monthlyOAS-monthlyDeduction,rows};
}
export function returnWorkBudget(input){
  let monthly=input.netPay-input.care-input.commute-input.otherWork-input.lostIncome;if(Math.abs(monthly)<1e-8)monthly=0;
  const rows=Array.from({length:input.months+1},(_,x)=>({x,value:-input.setup+x*monthly}));
  const recoveryMonth=input.setup===0?0:monthly>0?Math.max(1,Math.ceil(input.setup/monthly-1e-10)):null;
  return {monthly,rows,total:rows.at(-1).value,recoveryMonth,withinHorizon:recoveryMonth!==null&&recoveryMonth<=input.months};
}

export function paymentWorkResult(kind,input){
  if(kind==='rrspCash'){
    const p=rrspWithdrawalCash(input);
    return {metrics:[['Tax withheld on the modeled withdrawal',p.withheld,'money'],['Net cash at the withdrawal, after separate fee',p.immediate,'money'],['Extra tax / excess withholding under the assumption',p.settlement,'money']],note:'Ordinary single lump-sum RRSP request for a Canadian resident outside Quebec, using CRA withholding rates reviewed 25 October 2026. The applicable 10%, 20% or 30% applies to the entire gross request, not marginal bands. Withholding is rounded to cents for this illustration. Fee is paid separately and applies only to a positive withdrawal. A fee larger than available proceeds creates a cash need, not a negative institutional payout. The final-tax input is an independent assumed effective incremental rate on the whole withdrawal, not an actual bracket or tax-return calculation. A negative settlement means excess withholding under that assumption, not an approved refund or arrival date. Quebec, non-residents, spousal attribution, registered-plan programs, series/aggregation rules, benefit reductions and fee deductibility are outside this model.',charts:[
      {id:'rrsp-withholding-thresholds',type:'stackbar',title:'Withholding thresholds affect the whole request',unit:'money',seriesNames:['Proceeds before separate fee','Tax withheld'],source:paymentRules.rrspUrl,sourceLabel:'CRA · RRSP withdrawal withholding rates',evidence:'Rule-based illustration · hypothetical single requests',rows:[5000,5000.01,15000,15000.01,20000].map(gross=>{const withheld=cents(gross*rrspWithholdingRate(gross));return {label:'Gross CAD '+gross.toLocaleString('en-CA',{minimumFractionDigits:2}),values:[gross-withheld,withheld]};}),note:'Separate requests are shown only to explain the amount thresholds. They are not a proposed sequence of withdrawals or a way to reduce withholding. Fees are excluded. Crossing a threshold can reduce immediate proceeds because the higher rate applies to the whole request; it does not establish the final tax cost.'},
      {id:'rrsp-immediate-cash',type:'waterfall',title:'Reconcile the withdrawal to cash available immediately',unit:'money',rows:[{label:'Gross RRSP withdrawal',value:input.gross},{label:'Tax withheld by institution',value:-p.withheld},{label:'Separate transaction fee',value:-p.fee}],totalLabel:'Net transaction cash',note:'The institution’s modeled payment is gross less withholding; the separately paid fee then reduces the household’s net transaction cash. A negative endpoint is other cash required for the fee. Withholding is prepaid tax and is not subtracted again when the full assumed tax cost is compared below.'},
      {id:'rrsp-tax-comparison',type:'groupbar',title:'Compare prepaid withholding with an independent tax assumption',unit:'money',seriesNames:['Tax already withheld','Assumed incremental final tax'],rows:[...new Set([10,20,input.taxEstimate,40,50])].sort((a,b)=>a-b).map(taxEstimate=>({label:taxEstimate+'% final-tax assumption',values:[p.withheld,input.gross*taxEstimate/100]})),note:'Rows change the effective incremental tax assumption on the whole selected withdrawal. Withholding stays fixed for that request. Final tax above withholding implies a modeled extra amount; below withholding implies a credit under the assumption. Neither bar is a full tax-return assessment.'},
      {id:'rrsp-spending-matrix',type:'heatmap',signed:true,title:'Final cash above or below the intended spending amount',unit:'money',columns:['$5k','$10k','$15k','$20k'],rows:[20,30,40,50].map(taxEstimate=>({label:taxEstimate+'%',values:[5000,10000,15000,20000].map(gross=>rrspWithdrawalCash({...input,gross,taxEstimate}).spendingBalance)})),note:'Columns replace the single gross withdrawal; rows replace the assumed effective incremental tax rate. Selected fee and spending need stay fixed. Cells use gross less the full assumed tax and fee, then subtract spending need. They do not subtract withholding a second time. Positive cells are excess modeled final cash; negative cells are shortfalls, with no refund or settlement date assumed.'}
    ]};
  }
  if(kind==='oasRecovery'){
    const p=oasRecoveryPlan(input),points=[...new Set([0,50000,paymentRules.oasThreshold,100000,125000,150000,175000,200000,paymentRules.oasThreshold+input.annualOAS/paymentRules.oasRate,input.income])].sort((a,b)=>a-b);
    return {metrics:[['Simplified recovery on 2025 OAS',p.recovery,'money'],['New modeled monthly recovery deduction',p.monthlyDeduction,'money'],['Monthly OAS after that deduction only',p.monthlyRetained,'money']],note:'Dated 2025-income illustration for an OAS-only Canadian-resident case: 15% of relevant adjusted income above CAD 93,454, capped at entered 2025 OAS. Enter the appropriate income after CRA worksheet adjustments, including OAS where applicable; it is not added again. No GIS/net federal supplements, EI repayment, special adjustments, non-resident tax, ordinary income tax or actual return balance is calculated. The later cash chart holds gross monthly OAS constant from January 2026 through June 2027 and changes the recovery deduction in July 2026. New deduction is the simplified annual recovery divided by twelve, rounded to cents, then capped at monthly gross OAS. Rounding or that cap can make twelve deductions differ from the annual illustration. The cap does not cancel an actual tax obligation. Prior January–June deduction is separately entered and capped at gross. Actual deductions require the Advisory Letter; quarterly pension changes and any approved waiver are not modeled.',charts:[
      {id:'oas-income-recovery',type:'line',title:'The recovery starts above the dated income threshold',unit:'money',xUnit:'money',xLabel:'2025 adjusted income (CAD)',source:paymentRules.oasUrl,sourceLabel:'Service Canada · OAS repayment',evidence:'Simplified rule illustration · 2025 income',series:[{name:'Recovery with selected 2025 OAS cap',rows:points.map(income=>({x:income,value:oasRecoveryPlan({...input,income}).recovery}))}],note:'The income axis uses the relevant 2025 recovery-calculation income. The pension cap stays at the selected 2025 amount. The threshold is for 2025 and is not reused as a future-year threshold. This simplified OAS-only curve is not the complete Federal Worksheet or a prediction of actual deductions.'},
      {id:'oas-annual-bridge',type:'waterfall',title:'Separate 2025 OAS from its simplified recovery',unit:'money',rows:[{label:'Gross OAS received in 2025',value:input.annualOAS},{label:'Simplified 2025 recovery',value:-p.recovery}],totalLabel:'OAS after recovery only',note:'This bridge concerns 2025 benefits. Its endpoint is before ordinary income tax and excludes supplements. It is not twelve times the future monthly cash result, which concerns a later payment period and can use a different gross pension amount.'},
      {id:'oas-deduction-calendar',type:'line',title:'The later deduction can change in July rather than January',unit:'money',xMin:1,xLabel:'OAS payment month',xTicks:[{value:1,label:'Jan 26'},{value:7,label:'Jul 26'},{value:13,label:'Jan 27'},{value:18,label:'Jun 27'}],series:[{name:'Hypothetical gross monthly OAS',rows:p.rows.map(r=>({x:r.x,value:r.gross})),step:true},{name:'After recovery deduction only',rows:p.rows.map(r=>({x:r.x,value:r.retained})),step:true,dash:true}],note:'The old entered deduction applies in January–June 2026; the new illustration applies in July 2026–June 2027. Data-table indices 1–6 are January–June 2026, 7 is July 2026, 13 is January 2027 and 18 is June 2027. The Advisory Letter determines actual withholding. Later withholding is a credit for its payment year, not a second charge to add to the modeled 2025 recovery.'},
      {id:'oas-recovery-matrix',type:'heatmap',title:'Annual recovery across income and gross OAS received',unit:'money',columns:['$6k','$8k','$10k','$12k'],rows:[90000,100000,120000,150000].map(income=>({label:'$'+income/1000+'k',values:[6000,8000,10000,12000].map(annualOAS=>oasRecoveryPlan({...input,income,annualOAS}).recovery)})),note:'Rows replace relevant adjusted 2025 income; columns replace total 2025 OAS received. Income already includes the appropriate OAS amount; a column change holds total adjusted income fixed, implying an offset elsewhere rather than adding OAS again. Pension amounts are hypothetical and are not official annual maxima or eligibility determinations.'}
    ]};
  }
  if(kind==='returnWork'){
    const p=returnWorkBudget(input),observation={source:childcareSource.url,sourceLabel:'Statistics Canada · Child care arrangements, 2025',evidence:'Official statistics · dated parent-reported expenses'};
    return {metrics:[['Monthly household cash change',p.monthly,'money'],['Cumulative change after '+input.months+' months and setup',p.total,'money'],['Setup cost recovered by month',p.withinHorizon?p.recoveryMonth:null,'months',p.recoveryMonth===null?'Not recovered':!p.withinHorizon?'Beyond horizon':undefined]],note:'Two fixed official-data graphics provide context; the household controls are separate hypothetical assumptions. Additional take-home pay is already net of payroll deductions. Care, commuting and work costs are incremental to the comparison baseline; lost income is other net household income that stops or falls, entered independently. All recurring changes apply for every selected full month, with the first month’s full pay received inside that month; no payroll delay is modeled. Setup is paid at time zero. Cumulative difference is relative to the same non-return baseline, not an actual bank balance. Setup recovery is the first nonnegative month inside the horizon; zero setup means month zero even if later cash change is negative. No subsidy, child-care deduction, income tax, benefit eligibility, pension accrual, career progression or non-financial value is calculated.',charts:[
      {id:'work-childcare-national',type:'bar',...observation,title:'Published full-time centre-based child-care expenses by year',unit:'money',unitLabel:'Mean parent-reported current CAD per month',rows:childcareSource.national.map(r=>({label:String(r.year),value:r.value})),note:'Children aged 0–5 using full-time centre-based care, defined as 30+ hours per week. The 2022 comparison excludes territories; 2023 and 2025 include them and use differing survey sources. These are published current-dollar means, not a price index, individual fee quote, median or causal policy estimate.'},
      {id:'work-childcare-regions',type:'bar',...observation,source:childcareSource.chartUrl,sourceLabel:'Statistics Canada · Chart 1 and Table 42-10-0053-01',title:'The 2025 published means differ across provinces and territories',unit:'money',unitLabel:'2025 mean parent-reported current CAD per month',rows:[...childcareSource.regions].sort((a,b)=>a.value-b.value),note:'Thirteen 2025 observations for children aged 0–5 in full-time centre-based care. The national mean is weighted, not the simple average of these bars. Regional means do not describe every provider or family, guarantee a space, or rank care quality. Missing 2022 territory observations are not used as prices.'},
      {id:'work-monthly-cash',type:'waterfall',title:'Additional take-home pay is only the first budget line',unit:'money',rows:[{label:'Additional take-home work pay',value:input.netPay},{label:'Additional household child care',value:-input.care},{label:'Additional commuting',value:-input.commute},{label:'Other additional work costs',value:-input.otherWork},{label:'Other net household income lost',value:-input.lostIncome}],totalLabel:'Monthly household cash change',note:'Each amount is an incremental monthly change compared with not returning under the selected baseline. A subsidy already reflected in the provider’s net quote must not be subtracted again. The lost-income line is not a second payroll deduction. Existing unaffected household income and expenses cancel out of this comparison.'},
      {id:'work-setup-path',type:'line',title:'Recovering setup costs takes time after work begins',unit:'money',xLabel:'Full months after returning',series:[{name:'Cumulative household cash difference',rows:p.rows}],note:'The curve begins at the negative one-time setup cost. Each full month adds the selected recurring net cash change. Crossing zero recovers setup under these assumptions; it does not value career development, care quality, time, pension growth or job security. An improving curve can still require cash before the first pay arrives.'},
      {id:'work-care-pay-matrix',type:'heatmap',signed:true,title:'Monthly cash changes across care costs and take-home pay',unit:'money',columns:['$2k','$3k','$4k','$5k'],rows:[500,1000,1500,2000].map(care=>({label:'$'+care,values:[2000,3000,4000,5000].map(netPay=>returnWorkBudget({...input,care,netPay}).monthly)})),note:'Rows replace additional monthly care cost for the household; columns replace additional monthly take-home pay. Commuting, other work costs and other income lost remain selected. These cells are hypothetical monthly differences, not official fee observations, benefit calculations or a recommendation about returning to work.'}
    ]};
  }
  throw Error('Unknown payment or work planning topic.');
}
